import * as THREE from './vendor/three.module.js';
import {pointInside,nearestOnSegment,project} from './core.js';

const norm=s=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,'').replace(/\s+/g,' ').trim();
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const mats=new Map();
function mat(c,r=.9){const k=c+','+r;if(!mats.has(k))mats.set(k,new THREE.MeshStandardMaterial({color:c,roughness:r}));return mats.get(k);}
function box(g,c,x,y,z,w,h,d){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=w*h*d>100;m.receiveShadow=true;g.add(m);return m;}
function column(g,c,x,y,z,r,h){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r*1.04,h,12),mat(c));m.position.set(x,y,z);m.castShadow=false;m.receiveShadow=true;g.add(m);return m;}
function paving(g,c,x,y,z,w,d){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),mat(c));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);m.receiveShadow=true;g.add(m);return m;}
function plaque(g,text,x,y,z,w=8){if(typeof document==='undefined')return;const c=document.createElement('canvas');c.width=512;c.height=96;const q=c.getContext('2d');q.fillStyle='#e8dcc3';q.font='700 40px Georgia,serif';q.textAlign='center';q.textBaseline='middle';q.fillText(text,256,48);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const m=new THREE.Mesh(new THREE.PlaneGeometry(w,1.1),new THREE.MeshBasicMaterial({map:t,transparent:true,toneMapped:false}));m.position.set(x,y,z);g.add(m);}
function cross(g,x,y,z,s=.6){box(g,'#655f51',x,y,z,.16*s,1.6*s,.16*s);box(g,'#655f51',x,y+.28*s,z,.9*s,.15*s,.16*s);}
function frame(b){if(!b?.p?.length)return null;let edge=null,best=0;for(let i=0;i<b.p.length;i++){const a=b.p[i],q=b.p[(i+1)%b.p.length],d=Math.hypot(q[0]-a[0],q[1]-a[1]);if(d>best){best=d;edge=[a,q];}}if(!edge)return null;const [a,q]=edge,dx=(q[0]-a[0])/best,dz=(q[1]-a[1])/best,px=-dz,pz=dx,cx=b.cx??(a[0]+q[0])/2,cz=b.cz??(a[1]+q[1])/2;let lo=Infinity,hi=-Infinity;for(const v of b.p){const s=(v[0]-cx)*px+(v[1]-cz)*pz;lo=Math.min(lo,s);hi=Math.max(hi,s);}return {cx,cz,yaw:Math.atan2(dx,dz),length:best,width:Math.max(8,hi-lo)};}
function findBuilding(data,aliases){const aa=aliases.map(norm);let best=null,score=-1;for(const b of data.buildings||[]){const n=norm(b.n);if(!n||!aa.some(a=>n===a||n.includes(a)))continue;const area=Math.max(1,(b.maxX-b.minX)*(b.maxZ-b.minZ)),s=(aa.includes(n)?1e6:0)+area;if(s>score){best=b;score=s;}}return best;}
function authored(b){if(b){b.authoredLandmark=true;b.modelActive=true;}}
function frontWindows(g,w,z,ys=[5.2,8.2]){for(const y of ys)for(let x=-w*.38;x<=w*.38;x+=Math.max(3.2,w/6)){box(g,'#405a61',x,y,z,1.25,1.7,.12);box(g,'#ddcdb0',x,y-1.02,z+.02,1.55,.16,.15);}}
function localColonnade(g,w,z,depth=3.6,count=7){box(g,'#bca987',0,4.15,z-depth*.5,w+.7,.35,depth+.5);for(let i=0;i<=count;i++){const x=-w/2+i*w/count;column(g,'#ddd1ba',x,2,z-depth*.88,.25,4);box(g,'#d7c8aa',x,4,z-depth*.45,.5,.25,depth*.9);}}
function makePedrocchi(data,terrain){const b=findBuilding(data,['Caffè Pedrocchi','Cafe Pedrocchi','Pedrocchi']),p=project(45.4079,11.8778),f=b?frame(b):{cx:p.x,cz:p.z,yaw:.04,width:29,length:43};authored(b);const g=new THREE.Group();g.userData.poi='pedrocchi';g.userData.centre={x:f.cx,z:f.cz};g.userData.maxDistance=560;g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,24,36),l=clamp(f.length,34,52),h=11.5;box(g,'#d9d0bc',0,h/2,0,w,h,l);box(g,'#c8b895',0,h+.35,0,w+1,.7,l+1);box(g,'#987960',0,h+.82,0,w+.45,.22,l+.45);frontWindows(g,w,l/2+.08);localColonnade(g,w*.92,l/2+.35,4,8);for(const side of [-1,1]){const q=new THREE.Group();q.position.set(side*(w/2+2.15),0,l*.14);g.add(q);box(q,'#d8cdb7',0,4.15,0,4.2,.34,8);for(const z of [-3,-1,1,3])column(q,'#ddd2bc',0,2,z,.27,4);box(q,'#baa886',0,.2,0,4.7,.35,8.5);}plaque(g,'PEDROCCHI',0,9.6,l/2+.2,8);return g;}
function makeMoroni(data,terrain){const b=findBuilding(data,['Palazzo Moroni','Municipio di Padova','Municipio']),f=b?frame(b):{cx:-45,cz:-60,yaw:0,width:34,length:48};authored(b);const g=new THREE.Group();g.userData.poi='palazzo-moroni';g.userData.centre={x:f.cx,z:f.cz};g.userData.maxDistance=560;g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,24,44),l=clamp(f.length,30,58),h=14;box(g,'#ccb894',0,h/2,0,w,h,l);box(g,'#aa8e6c',0,h+.35,0,w+.8,.7,l+.8);frontWindows(g,w,l/2+.1,[7.2,10.3]);box(g,'#4c4439',0,2.65,l/2+.2,3.4,5.3,.17);for(const x of [-2.4,2.4])column(g,'#d8c8aa',x,3,l/2+.35,.31,6);box(g,'#d8c8aa',0,6.15,l/2+.34,6,.3,.5);plaque(g,'MUNICIPIO',0,11.7,l/2+.22,7);return g;}
function makeBo(data,terrain){const b=findBuilding(data,['Palazzo del Bo','Palazzo Bo','Università degli Studi di Padova','Universita degli Studi di Padova']),p=project(45.4071,11.8772),f=b?frame(b):{cx:p.x,cz:p.z,yaw:.02,width:36,length:55};authored(b);const g=new THREE.Group();g.userData.poi='palazzo-bo';g.userData.centre={x:f.cx,z:f.cz};g.userData.maxDistance=560;g.position.set(f.cx,terrain.elevation(f.cx,f.cz),f.cz);g.rotation.y=f.yaw;const w=clamp(f.width,28,48),l=clamp(f.length,38,64),h=13;box(g,'#c7b08d',0,h/2,0,w,h,l);box(g,'#a88d6d',0,h+.3,0,w+.8,.6,l+.8);frontWindows(g,w,l/2+.12,[8.1,10.7]);box(g,'#4b4438',0,2.7,l/2+.2,3.2,5.4,.16);localColonnade(g,w*.82,l/2+.34,3.5,7);plaque(g,'UNIVERSITÀ · BO',0,11.2,l/2+.23,10);return g;}
function makeSignori(terrain){const g=new THREE.Group();g.userData.poi='piazza-signori-complete';g.userData.centre={x:-282,z:-140};g.userData.maxDistance=650;const y=terrain.elevation(-282,-140);paving(g,'#b8aa90',-282,y+.055,-140,98,62);paving(g,'#c8baa0',-282,y+.065,-140,70,39);const tx=-336,tz=-162;
 for(const side of [-1,1]){const wing=new THREE.Group();wing.position.set(tx-3,y,tz+side*22);g.add(wing);box(wing,'#c9b28d',0,6,0,13,12,34);box(wing,'#ad8d68',6.58,6,0,.24,11.5,33);for(let z=-13;z<=13;z+=6.5){box(wing,'#42575a',6.72,7.7,z,.14,1.55,1.55);column(wing,'#d9c8aa',6.9,2.2,z,.25,4.4);}box(wing,'#d9c8aa',6.9,4.45,0,.35,.35,33.5);box(wing,'#b49b77',0,12.35,0,13.6,.7,34.4);}
 for(const [x,z] of [[-319,-115],[-299,-112],[-278,-112],[-258,-117],[-318,-162],[-296,-165],[-272,-165],[-250,-158]]){box(g,'#303d3e',x,y+1.8,z,.1,3.6,.1);box(g,'#e5bf72',x,y+3.68,z,.34,.16,.34);}
 for(const [x,z,r] of [[-307,-139,0],[-279,-142,0],[-257,-139,0],[-292,-120,Math.PI/2]]){const b=new THREE.Group();b.position.set(x,y,z);b.rotation.y=r;g.add(b);box(b,'#66523f',0,.48,0,2.3,.12,.42);box(b,'#343f3f',0,.25,0,2.05,.5,.08);}
 const well=new THREE.Group();well.position.set(-285,y,-143);g.add(well);const basin=new THREE.Mesh(new THREE.CylinderGeometry(2.1,2.35,.7,18),mat('#aaa18c'));basin.position.y=.35;well.add(basin);column(well,'#827969',0,1.25,0,.45,1.8);cross(well,0,2.6,0,.55);return g;}
function roadClearance(data,x,z){let best=Infinity;for(const r of data.roads||[]){if(['footway','path','cycleway','steps','pedestrian','tram'].includes(r.k))continue;for(let i=1;i<r.p.length;i++){const p=nearestOnSegment(x,z,r.p[i-1],r.p[i]),d=Math.hypot(p.x-x,p.z-z)-(r.w||5)/2;if(d<best)best=d;}}return best;}
function arcadeEdge(b,data,maxLength=30){if(!b?.p?.length)return null;let best=null;for(let i=0;i<b.p.length;i++){const a=b.p[i],q=b.p[(i+1)%b.p.length],len=Math.hypot(q[0]-a[0],q[1]-a[1]);if(len<12)continue;const dx=(q[0]-a[0])/len,dz=(q[1]-a[1])/len,mx=(a[0]+q[0])/2,mz=(a[1]+q[1])/2;let nx=-dz,nz=dx;if(pointInside(mx+nx*.4,mz+nz*.4,b.p)){nx=-nx;nz=-nz;}const c1=roadClearance(data,mx+nx*1.8,mz+nz*1.8),c2=roadClearance(data,mx+nx*3.4,mz+nz*3.4),clear=Math.min(c1,c2),score=clear+Math.min(len,maxLength)*.04;if(!best||score>best.score)best={mx,mz,dx,dz,nx,nz,length:Math.min(len,maxLength),clear,score};}return best&&best.clear>2.8?best:null;}
function addPortico(root,b,data,terrain,maxLength=28){const e=arcadeEdge(b,data,maxLength);if(!e)return false;const x=e.mx+e.nx*1.6,z=e.mz+e.nz*1.6,g=new THREE.Group(),y=terrain.elevation(x,z);g.position.set(x,y,z);g.rotation.y=Math.atan2(e.nx,e.nz);g.userData.passablePortico=true;g.userData.name=b.n||'Portico';const w=Math.max(12,e.length),depth=3.2;box(g,'#baa581',0,4.1,0,w,.34,depth);box(g,'#cbb896',0,4.45,0,w+.3,.24,depth+.25);const count=Math.max(4,Math.floor(w/4));for(let i=0;i<=count;i++){const px=-w/2+i*w/count;column(g,'#d8c6a7',px,2,depth*.38,.24,4);box(g,'#d8c6a7',px,3.95,0,.44,.28,depth*.8);}root.add(g);return true;}
function makePorticos(data,terrain){const root=new THREE.Group();root.userData.poi='passable-porticos';root.userData.centre={x:-180,z:-90};root.userData.maxDistance=700;let count=0,candidates=[];for(const aliases of [['Palazzo Moroni','Municipio'],['Palazzo del Bo','Università degli Studi di Padova'],['Caffè Pedrocchi','Pedrocchi'],['Palazzo della Ragione'],['Palazzo Capitanio','Capitanio']]){const b=findBuilding(data,aliases);if(b&&!candidates.includes(b))candidates.push(b);}for(const b of candidates){if(count>=6)break;if(addPortico(root,b,data,terrain,b.n?.includes('Ragione')?34:27))count++;}root.userData.porticoCount=count;return root;}
function piazzaAccents(terrain){const g=new THREE.Group();g.userData.poi='piazza-accents';g.userData.centre={x:-180,z:-45};g.userData.maxDistance=650;for(const [x,z,w,d] of [[-145,-48,67,30],[-205,-67,54,24],[-346,-12,54,28]])paving(g,'#bcae95',x,terrain.elevation(x,z)+.045,z,w,d);return g;}
export function createHistoricCenter(data,terrain){const root=new THREE.Group();root.userData.poi='historic-center-upgrade';const signori=makeSignori(terrain),pedrocchi=makePedrocchi(data,terrain),cityHall=makeMoroni(data,terrain),bo=makeBo(data,terrain),porticos=makePorticos(data,terrain),accents=piazzaAccents(terrain);root.add(signori,pedrocchi,cityHall,bo,porticos,accents);const groups=[signori,pedrocchi,cityHall,bo,porticos,accents];return {root,signori,pedrocchi,cityHall,bo,porticos,accents,update(x,z){for(const g of groups){const c=g.userData.centre||g.position;const cx=Number.isFinite(c.x)?c.x:-180,cz=Number.isFinite(c.z)?c.z:-80;g.visible=Math.hypot(x-cx,z-cz)<(g.userData.maxDistance||650);}}};}
